package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct string // PIC X(4) @0 len=4
	ScPrin decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64 // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsBal decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99 len=10 = 0
var WsYear int64 = 0 // PIC 99 len=2 = 0
var WsCount int64 = 0 // PIC 99 len=2 = 0
var WsBalEd string = "             " // PIC ZZ,ZZZ,ZZ9.99 len=13

var schedRec SchedRec
var schedLines []string
var schedIdx int

func InputDone() bool {
	return WsEofFlag == "Y"
}

func truncPic99(v int64) int64 {
	r := v % 100
	if r < 0 {
		r += 100
	}
	return r
}

func storeWsBal(d decimal.Decimal) decimal.Decimal {
	scaled := d.Shift(2).Truncate(0)
	n := scaled.IntPart()
	const mod int64 = 10000000000
	r := n % mod
	return decimal.New(r, -2)
}

func parseScaled(s string, scale int32) decimal.Decimal {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return decimal.New(n, -scale)
}

func parseIntField(s string) int64 {
	var n int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		n = n*10 + d
	}
	return n
}

func formatPic99(v int64) string {
	v = truncPic99(v)
	return fmt.Sprintf("%02d", v)
}

func formatWsBalEd(v decimal.Decimal) string {
	av := v
	if av.IsNegative() {
		av = av.Neg()
	}
	av = av.Truncate(2)
	scaled := av.Shift(2).Truncate(0)
	n := scaled.IntPart()
	n = n % 10000000000
	if n < 0 {
		n = -n
	}
	intPart := n / 100
	fracPart := n % 100
	intDigits := fmt.Sprintf("%08d", intPart)
	fracDigits := fmt.Sprintf("%02d", fracPart)
	first := 8
	for i := 0; i < 8; i++ {
		if intDigits[i] != '0' {
			first = i
			break
		}
	}
	intPic := "ZZ,ZZZ,ZZ9"
	res := make([]byte, 0, 10)
	idx := 0
	for i := 0; i < len(intPic); i++ {
		c := intPic[i]
		if c == 'Z' || c == '9' {
			d := intDigits[idx]
			idx++
			if c == '9' {
				res = append(res, d)
			} else {
				if idx-1 < first {
					res = append(res, ' ')
				} else {
					res = append(res, d)
				}
			}
		} else if c == ',' {
			if first < idx {
				res = append(res, ',')
			} else {
				res = append(res, ' ')
			}
		} else {
			res = append(res, c)
		}
	}
	return string(res) + "." + fracDigits
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if len(data) == 0 {
		schedLines = nil
	} else {
		text := string(data)
		parts := strings.Split(text, "\n")
		if strings.HasSuffix(text, "\n") {
			parts = parts[:len(parts)-1]
		}
		schedLines = make([]string, 0, len(parts))
		for _, p := range parts {
			if strings.HasSuffix(p, "\r") {
				p = strings.TrimSuffix(p, "\r")
			}
			schedLines = append(schedLines, p)
		}
	}
	schedIdx = 0
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	fmt.Printf("SCHEDULES: %s\n", formatPic99(WsCount))
}

func ReadPara() {
	if schedIdx < len(schedLines) {
		line := schedLines[schedIdx]
		schedIdx++
		if len(line) < 16 {
			line += strings.Repeat(" ", 16-len(line))
		} else if len(line) > 16 {
			line = line[:16]
		}
		schedRec.ScAcct = line[0:4]
		schedRec.ScPrin = parseScaled(line[4:11], 2)
		schedRec.ScRate = parseScaled(line[11:15], 2)
		schedRec.ScYears = parseIntField(line[15:16])
	} else {
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	WsBal = storeWsBal(schedRec.ScPrin)
	WsYear = truncPic99(1)
	for !(WsYear > schedRec.ScYears) {
		factor := decimal.NewFromInt(1).Add(schedRec.ScRate.Shift(-2))
		prod := WsBal.Mul(factor)
		rounded := prod.Round(2)
		WsBal = storeWsBal(rounded)
		WsBalEd = formatWsBalEd(WsBal)
		fmt.Printf("%s Y%s %s\n", schedRec.ScAcct, formatPic99(WsYear), WsBalEd)
		WsYear = truncPic99(WsYear + 1)
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", schedRec.ScAcct, WsBalEd)
	WsCount = truncPic99(WsCount + 1)
	ReadPara()
}

func main() {
	MainPara()
}
